import Foundation

/// All emoji the palette offers, with a search over their names, keywords and
/// shortcodes. Built once from the bundled `emoji.json` (generated by
/// `scripts/generate-emoji-data.py`); the search index is folded up front, so
/// a search per keystroke is cheap.
public struct EmojiCatalog: Sendable {
    /// The newest Unicode emoji version macOS can draw; newer entries are
    /// left out instead of showing as boxes. Raise it with the OS support.
    public static let maxVersion = 16.0

    public static let shared = EmojiCatalog.bundled()

    /// In Unicode order (by group).
    public let emoji: [Emoji]
    /// Language codes with names and keywords in the data.
    public let languages: [String]
    private let index: [Entry]
    /// Position in `emoji` by character.
    private let positions: [String: Int]

    /// Languages to search and name emoji in: the user's preferred ones the
    /// data has, then English.
    public func languages(preferred: [String] = Locale.preferredLanguages) -> [String] {
        var result: [String] = []
        for identifier in preferred {
            let code = Locale(identifier: identifier).language.languageCode?.identifier ?? identifier
            if languages.contains(code), !result.contains(code) { result.append(code) }
        }
        if !result.contains("en") { result.append("en") }
        return result
    }

    public func group(_ group: EmojiGroup) -> [Emoji] {
        emoji.filter { $0.group == group }
    }

    public init(data: Data, maxVersion: Double = EmojiCatalog.maxVersion) throws {
        let file = try JSONDecoder().decode(File.self, from: data)
        emoji = file.emoji.filter { $0.v <= maxVersion }.compactMap { record in
            guard let group = EmojiGroup(rawValue: record.g) else { return nil }
            return Emoji(
                character: record.c, group: group, order: record.o, version: record.v,
                shortcodes: record.s, skinTones: record.t ?? [],
                names: record.l.mapValues(\.n), keywords: record.l.mapValues(\.k))
        }
        languages = file.languages
        index = emoji.map(Entry.init)
        positions = Self.positions(of: emoji)
    }

    static func bundledData() -> Data? {
        Bundle.module.url(forResource: "emoji", withExtension: "json").flatMap { try? Data(contentsOf: $0) }
    }

    private static func bundled() -> EmojiCatalog {
        guard let data = bundledData(), let catalog = try? EmojiCatalog(data: data)
        else {
            Log.logger("emoji").error("emoji.json is missing or unreadable")
            return EmojiCatalog(emoji: [], languages: ["en"])
        }
        return catalog
    }

    private init(emoji: [Emoji], languages: [String]) {
        self.emoji = emoji
        self.languages = languages
        index = []
        positions = Self.positions(of: emoji)
    }

    private static func positions(of emoji: [Emoji]) -> [String: Int] {
        Dictionary(emoji.enumerated().map { ($1.character, $0) }, uniquingKeysWith: { first, _ in first })
    }

    // MARK: - Search

    /// Emoji matching every word of `query` (a name or keyword in one of
    /// `languages`, or a shortcode; a leading or trailing colon is ignored),
    /// best match first. Ties go to the emoji used more, then to Unicode order.
    public func search(
        _ query: String, languages: [String] = ["en"], usage: UsageRanking = UsageRanking(), now: Date = .now
    ) -> [Emoji] {
        let words = query.split { $0.isWhitespace || $0 == ":" }.map { SnippetSearch.fold(String($0)) }
        guard !words.isEmpty else { return emoji }

        let scored: [(emoji: Emoji, score: Int, usage: Double)] = index.compactMap { entry in
            var total = 0
            for word in words {
                guard let score = entry.score(word, languages: languages) else { return nil }
                total += score
            }
            return (entry.emoji, total, usage.score(of: entry.emoji.character, now: now))
        }
        return scored.sorted {
            if $0.score != $1.score { return $0.score > $1.score }
            if $0.usage != $1.usage { return $0.usage > $1.usage }
            return ($0.emoji.group.rawValue, $0.emoji.order) < ($1.emoji.group.rawValue, $1.emoji.order)
        }.map(\.emoji)
    }

    /// The emoji for a character in its default tone.
    public func emoji(for character: String) -> Emoji? {
        positions[character].map { emoji[$0] }
    }

    private struct Entry: Sendable {
        let emoji: Emoji
        let shortcodes: [String]
        /// The shortcodes without `_` and `-`.
        let compactShortcodes: [String]
        /// Folded name, its words and the keywords, by language.
        let fields: [String: Fields]

        struct Fields: Sendable {
            let name: String
            let nameWords: [String]
            /// The name without spaces and punctuation, so `redheart` finds
            /// "red heart".
            let compactName: String
            let keywords: [String]
        }

        init(_ emoji: Emoji) {
            self.emoji = emoji
            shortcodes = emoji.shortcodes.map(SnippetSearch.fold)
            compactShortcodes = shortcodes.map(Self.compact)
            var fields: [String: Fields] = [:]
            for (language, name) in emoji.names {
                let folded = SnippetSearch.fold(name)
                let words = folded.split { !$0.isLetter && !$0.isNumber }.map(String.init)
                fields[language] = Fields(
                    name: folded,
                    nameWords: words,
                    compactName: words.joined(),
                    keywords: (emoji.keywords[language] ?? []).map(SnippetSearch.fold))
            }
            self.fields = fields
        }

        static func compact(_ text: String) -> String {
            String(text.filter { $0.isLetter || $0.isNumber })
        }

        /// Shortcodes and names are each tried as typed and then with spaces
        /// and punctuation left out on both sides, which ranks just below.
        func score(_ word: String, languages: [String]) -> Int? {
            var best: Int?
            func consider(_ score: Int) { best = max(best ?? score, score) }
            let compactWord = Self.compact(word)
            let compares = !compactWord.isEmpty

            if shortcodes.contains(word) { consider(100) }
            else if compares, compactShortcodes.contains(compactWord) { consider(90) }
            else if shortcodes.contains(where: { $0.hasPrefix(word) }) { consider(85) }
            else if compares, compactShortcodes.contains(where: { $0.hasPrefix(compactWord) }) { consider(75) }
            for language in languages {
                guard let fields = fields[language] else { continue }
                if fields.name == word { consider(95) }
                else if compares, fields.compactName == compactWord { consider(90) }
                else if fields.name.hasPrefix(word) { consider(80) }
                else if compares, fields.compactName.hasPrefix(compactWord) { consider(75) }
                else if fields.nameWords.contains(where: { $0.hasPrefix(word) }) { consider(70) }
                if fields.keywords.contains(word) { consider(65) }
                else if fields.keywords.contains(where: { $0.hasPrefix(word) }) { consider(55) }
                if fields.name.contains(word) { consider(40) }
                else if compares, fields.compactName.contains(compactWord) { consider(35) }
                else if fields.keywords.contains(where: { $0.contains(word) }) { consider(30) }
            }
            return best
        }
    }

    private struct File: Decodable {
        struct Record: Decodable {
            struct Localized: Decodable {
                let n: String
                let k: [String]
            }
            let c: String
            let o: Int
            let g: Int
            let v: Double
            let s: [String]
            let t: [String]?
            let l: [String: Localized]
        }
        let languages: [String]
        let emoji: [Record]
    }
}
